import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import {
  FallLocationWarning,
  FallLocationWarningFilters,
  FallLocationWarningStats,
} from '../../models/FallLocationWarning';
import { fallLocationWarningService } from '../../services/fallLocationWarnings';

interface FallLocationWarningsState {
  items: FallLocationWarning[];
  selectedWarning: FallLocationWarning | null;
  filters: FallLocationWarningFilters;
  loading: boolean;
  saving: boolean;
  error: string | null;
  stats: FallLocationWarningStats;
  pagination: { page: number; pageSize: number; totalCount: number };
}

const initialState: FallLocationWarningsState = {
  items: [],
  selectedWarning: null,
  filters: {},
  loading: false,
  saving: false,
  error: null,
  stats: { total: 0, notFixed: 0, inProgress: 0, fixed: 0, proposed: 0 },
  pagination: { page: 1, pageSize: 20, totalCount: 0 },
};

// ─── Thunks ───────────────────────────────────────────────────────────────────

export const fetchFallLocationWarnings = createAsyncThunk(
  'fallLocationWarnings/fetchList',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { fallLocationWarnings: FallLocationWarningsState };
    const { filters, pagination } = state.fallLocationWarnings;
    return fallLocationWarningService.getList(filters, pagination.page, pagination.pageSize);
  },
);

export const fetchFallLocationWarningStats = createAsyncThunk(
  'fallLocationWarnings/fetchStats',
  async () => fallLocationWarningService.getStats(),
);

export const fetchFallLocationWarningById = createAsyncThunk(
  'fallLocationWarnings/fetchById',
  async (id: string) => fallLocationWarningService.getById(id),
);

export const createFallLocationWarning = createAsyncThunk(
  'fallLocationWarnings/create',
  async (data: Partial<FallLocationWarning>) => fallLocationWarningService.create(data),
);

export const updateFallLocationWarning = createAsyncThunk(
  'fallLocationWarnings/update',
  async ({ id, data }: { id: string; data: Partial<FallLocationWarning> }) =>
    fallLocationWarningService.update(id, data),
);

export const deleteFallLocationWarning = createAsyncThunk(
  'fallLocationWarnings/delete',
  async (id: string) => {
    await fallLocationWarningService.delete(id);
    return id;
  },
);

// ─── Slice ────────────────────────────────────────────────────────────────────

const fallLocationWarningsSlice = createSlice({
  name: 'fallLocationWarnings',
  initialState,
  reducers: {
    setFilters(state, action: PayloadAction<FallLocationWarningFilters>) {
      state.filters = action.payload;
      state.pagination.page = 1;
    },
    setPage(state, action: PayloadAction<number>) {
      state.pagination.page = action.payload;
    },
    setSelectedWarning(state, action: PayloadAction<FallLocationWarning | null>) {
      state.selectedWarning = action.payload;
    },
    clearError(state) { state.error = null; },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchFallLocationWarnings.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchFallLocationWarnings.fulfilled, (s, a) => {
        s.loading = false;
        s.items = a.payload.items;
        s.pagination.totalCount = a.payload.total;
        s.pagination.page = a.payload.page;
      })
      .addCase(fetchFallLocationWarnings.rejected, (s, a) => {
        if (a.meta.aborted) return;
        s.loading = false;
        s.error = a.error.message ?? 'Lỗi tải danh sách';
      });

    builder.addCase(fetchFallLocationWarningStats.fulfilled, (s, a) => { s.stats = a.payload; });

    builder
      .addCase(fetchFallLocationWarningById.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchFallLocationWarningById.fulfilled, (s, a) => {
        s.loading = false;
        s.selectedWarning = a.payload;
      })
      .addCase(fetchFallLocationWarningById.rejected, (s, a) => {
        s.loading = false;
        s.error = a.error.message ?? 'Lỗi tải thông tin';
      });

    builder
      .addCase(createFallLocationWarning.pending, (s) => { s.saving = true; })
      .addCase(createFallLocationWarning.fulfilled, (s, a) => {
        s.saving = false;
        s.items.unshift(a.payload);
        s.pagination.totalCount += 1;
      })
      .addCase(createFallLocationWarning.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'Lỗi tạo mới';
      });

    builder
      .addCase(updateFallLocationWarning.pending, (s) => { s.saving = true; })
      .addCase(updateFallLocationWarning.fulfilled, (s, a) => {
        s.saving = false;
        const idx = s.items.findIndex((i) => i.id === a.payload.id);
        if (idx >= 0) s.items[idx] = a.payload;
        if (s.selectedWarning?.id === a.payload.id) s.selectedWarning = a.payload;
      })
      .addCase(updateFallLocationWarning.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'Lỗi cập nhật';
      });

    builder
      .addCase(deleteFallLocationWarning.fulfilled, (s, a) => {
        s.items = s.items.filter((i) => i.id !== a.payload);
        s.pagination.totalCount -= 1;
      });
  },
});

export const {
  setFilters,
  setPage,
  setSelectedWarning,
  clearError,
} = fallLocationWarningsSlice.actions;

export default fallLocationWarningsSlice.reducer;
