import type { FallLocationWarning, FallLocationWarningFilters, FallLocationWarningStats } from '../../models/FallLocationWarning';
import type { PagedResult } from './endpoint';
import { fallLocationWarningEndpoint } from './endpoint';

export const fallLocationWarningService = {
  getList: (
    filters: FallLocationWarningFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PagedResult<FallLocationWarning>> =>
    fallLocationWarningEndpoint.getList(filters, page, pageSize),

  getStats: (): Promise<FallLocationWarningStats> =>
    fallLocationWarningEndpoint.getStats(),

  getById: (id: string): Promise<FallLocationWarning | null> =>
    fallLocationWarningEndpoint.getById(id),

  create: (data: Partial<FallLocationWarning>): Promise<FallLocationWarning> =>
    fallLocationWarningEndpoint.create(data),

  update: (id: string, data: Partial<FallLocationWarning>): Promise<FallLocationWarning> =>
    fallLocationWarningEndpoint.update(id, data),

  delete: (id: string): Promise<void> =>
    fallLocationWarningEndpoint.delete(id),
};
